import { processBatch, classifySignal } from './process_batch';

function eq(a: unknown, b: unknown, msg: string) {
  const sa = JSON.stringify(a), sb = JSON.stringify(b);
  if (sa !== sb) { console.log('FAIL', msg, '\n got', sa, '\n exp', sb); process.exitCode = 1; }
  else console.log('PASS', msg);
}

// valid batch
const valid = {
  readings: [
    { channel: 'A', unit: 'mV', value: 100, at: 0 },
    { channel: 'B', unit: 'V', value: 1, at: 5 },      // ->

    { channel: 'A', unit: 'mV', value: -5, at: 15 },    // negative
  ]
};
const r = processBatch(valid);
eq(r.ok, true, 'valid ok');
eq(r.readings, 4, 'readings count');
eq(r.labels, ['idle','critical','active','negative'], 'labels');
eq(r.alerts, ['B:critical','A:negative'], 'alerts');
eq(r.channels['A'], {count:2,min:-5,max:100,worst:'negative'}, 'chan A');
eq(r.channels['B'], {count:1,min:1000,max:1000,worst:'critical'}, 'chan B');
eq(r.report, 'readings=4;channels=3;alerts=2;worst=negative', 'report');

// errors
eq(processBatch(null).ok, false, 'null');
eq((processBatch(null) as any).error, 'malformed batch', 'null err');
eq((processBatch({}) as any).error, 'missing readings', 'no readings');
eq((processBatch({readings: []}) as any).error, 'empty batch', 'empty');
eq((processBatch({readings: Array(501).fill({channel:'a',unit:'mV',value:1,at:0})})).ok, false, 'too large');
eq((processBatch({readings:[{unit:'mV',value:1,at:0}]} as any)).error, 'reading 0: bad channel', 'bad channel');
