export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts

?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const VALID_UNITS = new Set(["uV", "mV", "V"]);

// Signal severity ordering used for both per-channel "worst" tracking and the
// overall report. "standby" is the baseline (least severe).
const SEVERITY: Record<string, number> =

 {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
};

export function processBatch(raw: unknown): BatchResult {
  const validationError = validateBatch(raw);
  if (validationError !== null) {
    return { ok: false, error: validationError };
  }

  const parsed = parseAllReadings((raw as { readings: unknown[] }).readings);
  if (typeof parsed === "string") {
    return { ok: false, error: parsed };
  }

  const labels = parsed.map((reading) => classifySignal(reading.m

illivolts));
  const alerts = collectAlerts(parsed);
  const channels = channelSummaries(parsed, labels);
  const report = buildReport(parsed.length, Object.keys(channels).length, alerts.length, labels);
  return {
    ok: true,
    readings: parsed.length,
    labels,
    channels,
    alerts,
    report,
  };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if

(!Array.isArray(batch.readings)) {
   return "missing readings";
 }
 if (batch.readings.length === 0) {
   return "empty batch";
 }
 if (batch.readings.length >

 MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

/**
 * Parses every reading, short-circuiting with a formatted error message on the
 * first malformed entry. Returns either the list of parsed readings or an error.
 */
function parseAllReadings(entries: unknown[]): ParsedReading[] | string {
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
      return outcome;
    }
    parsed.push({
      channel: outcome.channel,
      millivolts: normalizeValue(outcome.unit, outcome.value),
      at: outcome.at,
    });
  }
  return parsed;
}

function parseReading(entry: unknown, index: number): Reading | string {
  const malformed = (field: string) =>

`reading ${index}: ${field}`;
 if (typeof entry !== "object" || entry === null) {
   return malformed("malformed");
 }
 const record = entry as Record<string, unknown>;

 if (typeof record.channel !== "string" || record.channel.length === 0) {
    return malformed("bad channel");
  }
  if (typeof record.unit !== "string" || !VALID_UNITS.has(record.unit)) {
    return malformed("bad unit");
  }
  if (!Number.isInteger(record.value)) {
